def transform(grid):
    h, w = len(grid), len(grid[0])
    candidates = []

    # Collect solid separator lines. Prefer the line with the most balanced
    # regions on its two sides (the separator is between matching-size fields).
    for r in range(h):
        if grid[r][0] != 0 and all(v == grid[r][0] for v in grid[r]):
            candidates.append((abs(r - (h - r - 1)), "row", r))
    for c in range(w):
        if grid[0][c] != 0 and all(row[c] == grid[0][c] for row in grid):
            candidates.append((abs(c - (w - c - 1)), "col", c))

    if not candidates:
        return [[0] * w for _ in grid]

    _, orient, k = min(candidates)

    if orient == "col":
        n = min(k, w - k - 1)
        return [
            [2 if row[i] != 0 and row[k + 1 + i] != 0 else 0
             for i in range(n)]
            for row in grid
        ]

    n = min(k, h - k - 1)
    return [
        [2 if grid[i][c] != 0 and grid[k + 1 + i][c] != 0 else 0
         for c in range(w)]
        for i in range(n)
    ]
